-- PROMPT demo seed: team_allocation database.
--
-- The Team Allocation phase of iPraktikumDemo
-- (f0000004-0000-0000-0000-000000000004): the skills and teams a lecturer
-- configures, the student survey responses, and the published allocation.
--
-- Deleting the teams and skills cascades the survey responses, allocations and
-- tutors that hang off them. Student names are denormalized copies of the core
-- `student` rows and no foreign key keeps them in sync.

DELETE FROM team WHERE course_phase_id = 'f0000004-0000-0000-0000-000000000004';
DELETE FROM skill WHERE course_phase_id = 'f0000004-0000-0000-0000-000000000004';
DELETE FROM survey_timeframe WHERE course_phase_id = 'f0000004-0000-0000-0000-000000000004';
DELETE FROM tease_workspace WHERE course_phase_id = 'f0000004-0000-0000-0000-000000000004';

